"""
验证架构师Agent —— 使用 generate_uvm 生成 UVM 组件代码

bypass 模式: 根据输入规格构造 YAML → generate_uvm() → 真实 SV 代码
LLM 模式:   通过 LangChain Agent + generate_uvm 工具生成
"""
from typing import Dict, List, Any
from langchain.agents import create_openai_tools_agent, AgentExecutor
from langchain.prompts import ChatPromptTemplate, MessagesPlaceholder

from src.core.base import BaseAgent, AgentResult
from src.core.registry import register_agent
from src.tools.uvm import generate_uvm
import structlog
import yaml

logger = structlog.get_logger()


@register_agent("verification_architect")
class VerificationArchitect(BaseAgent):
    """验证架构师Agent —— 使用参数化 generate_uvm 工具"""

    task_type = "code_generation"

    def __init__(self, config: Dict[str, Any] = None):
        super().__init__(
            role="verification_architect",
            display_name="验证架构师",
            description="设计UVM验证环境架构并生成所有组件代码",
            config=config or {}
        )

    async def _setup(self):
        logger.info(f"{self.display_name} 特定初始化完成")

    async def _get_prompt_template(self):
        return ChatPromptTemplate.from_messages([
            ("system", """你是UVM验证环境架构设计专家。

【职责】
1. 设计UVM验证环境整体架构
2. 定义组件层次和接口
3. 调用 generate_uvm 工具生成所有UVM组件代码

【工具使用】
- generate_uvm(tool_type="agent", yaml_spec=...) → 生成 Agent 全套代码(Driver/Monitor/Sequencer/...)
- generate_uvm(tool_type="env", yaml_spec=...)   → 生成 Environment 全套代码
- generate_uvm(tool_type="bench", yaml_spec=...) → 生成 Testbench Top
- tool_type 可选: agent | env | bench | constraint | util

【代码生成规范】
- 遵循UVM 1.2标准
- 使用`uvm_component_utils宏注册
- 实现完整phase
- 正确的TLM端口声明和连接
            """),
            MessagesPlaceholder(variable_name="chat_history"),
            ("human", "{input}"),
            MessagesPlaceholder(variable_name="agent_scratchpad")
        ])

    async def _get_tools(self) -> List:
        return [generate_uvm]

    async def _execute(self, input_text: str) -> Dict[str, Any]:
        if self._executor:
            return await self._executor.ainvoke({"input": input_text})
        return {"output": "Agent未初始化"}

    # ── bypass: 不调 LLM，直接用 generate_uvm 生成真实代码 ──

    async def execute_task(self, task: Dict[str, Any]) -> AgentResult:
        bypass = task.get('bypass', False) if isinstance(task, dict) else False
        if not bypass:
            return await super().execute_task(task)

        from datetime import datetime
        import json
        start_time = datetime.now()
        self.status = self.__class__.AgentStatus.BUSY if hasattr(self.__class__, 'AgentStatus') else None

        try:
            spec_text = task.get("input", str(task))
            self._last_prompt = "bypass mode: generate_uvm"

            # 根据规格构造 UART Agent YAML
            uart_yaml = _build_uart_agent_yaml(spec_text)
            result_text = generate_uvm("agent", uart_yaml)

            execution_time = (datetime.now() - start_time).total_seconds()
            self.metrics["tasks_completed"] += 1
            self.metrics["total_time"] += execution_time

            from src.middleware.debug_logger import debug_logger
            debug_logger.log_agent_call(
                self.role, self.display_name, str(task)[:500],
                "generate_uvm(agent, ...)", result_text[:500],
                ["generate_uvm"], 0, execution_time, True
            )

            return AgentResult(success=True, data={"output": result_text}, execution_time=execution_time)
        except Exception as e:
            return AgentResult(success=False, error=str(e))


def _build_uart_agent_yaml(spec_text: str) -> str:
    """根据规格文本构造 UART Agent YAML"""
    interface_name = "uart_if"
    agent_name = "UART_in"

    return yaml.dump({
        "interfaces": {
            "name": agent_name,
            "clock": "pclk",
            "reset": "presetn",
            "parameters": [
                {"name": "DATA_WIDTH", "type": "int", "value": "8"},
                {"name": "FIFO_DEPTH", "type": "int", "value": "16"},
            ],
            "hdl_typedefs": [
                {"name": "uart_data_t", "type": "logic [7:0]"},
                {"name": "uart_parity_t", "type": "enum logic [1:0] {NONE=2'b00, EVEN=2'b01, ODD=2'b10}"},
            ],
            "hvl_typedefs": [
                {"name": "uart_result_t", "type": "bit [15:0]"},
            ],
            "ports": [
                {"name": "pclk",    "dir": "input",  "width": 1},
                {"name": "presetn", "dir": "input",  "width": 1},
                {"name": "tx",      "dir": "output", "width": 1},
                {"name": "rx",      "dir": "input",  "width": 1},
                {"name": "interrupt","dir": "output", "width": 1},
            ],
            "transaction_vars": [
                {"name": "data",      "type": "uart_data_t",   "iscompare": "True", "isrand": "True"},
                {"name": "parity",    "type": "uart_parity_t", "iscompare": "True", "isrand": "True"},
                {"name": "stop_bits", "type": "bit [1:0]",     "iscompare": "True", "isrand": "True"},
            ],
            "transaction_constraints": [
                {"name": "data_range_c", "value": "{ data inside {[0:255]}; }"},
            ],
            "config_vars": [
                {"name": "baud_rate", "type": "int", "value": "115200"},
                {"name": "is_active", "type": "bit", "value": "1"},
            ],
            "config_constraints": [
                {"name": "baud_valid_c", "value": "{ baud_rate inside {9600, 19200, 38400, 57600, 115200}; }"},
            ],
            "response_info": {
                "data": ["tx", "rx"],
                "operation": "1'b0",
            },
            "config": {"is_active": "UVM_ACTIVE"},
        }
    }, default_flow_style=False, allow_unicode=True)
